os.makedirs(BASE, exist_ok=True)
total = 0
written = 0
for cid in IDS:
    d = P[cid]
    obj = {"case_id": cid, "prediction_text": d["prediction_text"], "basis": d["basis"],
           "confidence": d["confidence"], "trigger": d["trigger"]}
    path = os.path.join(BASE, cid + ".json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=1)
    written += 1

# 逐件精确自验（只按本批 id 清单逐件打开，不枚举目录）
ok = 0
for cid in IDS:
    path = os.path.join(BASE, cid + ".json")
    with open(path, encoding="utf-8") as f:
        obj = json.load(f)
    assert obj["case_id"] == cid, cid
    for k in ("case_id", "prediction_text", "basis", "confidence", "trigger"):
        assert k in obj, (cid, k)
    assert 0.0 <= obj["confidence"] <= 1.0, cid
    for bk in ("changed_main", "reserve_used", "disputed", "reason"):
        assert bk in obj["trigger"], (cid, bk)
    total += os.path.getsize(path)
    ok += 1
assert written == 20 and ok == 20, (written, ok)
cm = sum(1 for c in IDS if P[c]["trigger"]["changed_main"])
ru = sum(1 for c in IDS if P[c]["trigger"]["reserve_used"])
di = sum(1 for c in IDS if P[c]["trigger"]["disputed"])
print("written=%d verified=%d total_bytes=%d changed_main=%d reserve_used=%d disputed=%d" % (written, ok, total, cm, ru, di))
